public static Object[] generateValidInput(Random random) {
    // Generate n: 1..20 (avoid 0 to prevent ArrayIndexOutOfBounds)
    int n = random.nextInt(20) + 1;

    // Generate k non-zero, with small absolute value to avoid overflow in multiplication
    int k;
    do {
        k = random.nextInt(200) - 100; // [-100, 99]
    } while (k == 0);

    // Decide whether to generate a valid (return non-negative) or invalid (return -1) case
    // For n == 1 or |k| == 1 only valid case is possible
    boolean validCase;
    if (n == 1 || Math.abs(k) == 1) {
        validCase = true;
    } else {
        validCase = random.nextBoolean();
    }

    int[] arr = new int[n];

    // Choose a maximum value (random within range)
    int max = random.nextInt(1000) - 500; // [-500, 499]

    if (validCase) {
        // All elements differ from max by a multiple of k
        for (int i = 0; i < n; i++) {
            int multiple = random.nextInt(10); // 0..9
            arr[i] = max - multiple * k;
        }
    } else {
        // Invalid case: at least one element's difference is not a multiple of k
        // Pick a random index to be the "bad" element
        int badIndex = random.nextInt(n);
        // First, fill all elements with valid multiples
        for (int i = 0; i < n; i++) {
            int multiple = random.nextInt(10);
            arr[i] = max - multiple * k;
        }
        // Now modify the bad element so that (max - arr[badIndex]) % k != 0
        // We can offset by 1 (or any non-multiple) but ensure no overflow
        // Since k != 0, we can add 1 to the difference, but careful with sign.
        int diff = max - arr[badIndex];
        // We want diff % k != 0, so we can change arr[badIndex] by ±1
        // However, if k == 1 or -1, this would still be divisible, but we already handled that.
        if (diff % k == 0) {
            // Change by 1
            arr[badIndex] = arr[badIndex] + 1;
        }
        // else it's already bad, leave as is
    }

    return new Object[]{arr, Integer.valueOf(n), Integer.valueOf(k)};
}

