    public static int longestIncreasingSubsequence(int[] arr) {
        int n = arr.length;
        int[] dp = new int[n];
        int max = 1;
        //@ loop_invariant 0 <= i && i <= n;
        //@ loop_invariant max >= 1 && max <= n;
        //@ loop_invariant (\forall int k; 0 <= k && k < i; 1 <= dp[k] && dp[k] <= k+1);
        //@ decreases n - i;
