            //@ loop_invariant 0 <= j && j <= i;
            //@ loop_invariant dp[i] >= 1 && dp[i] <= i+1;
            //@ loop_invariant (\forall int k; 0 <= k && k < i; 1 <= dp[k] && dp[k] <= k+1);
