            char c1 = (char) ('a' + random.nextInt(26));
            char c2;
            do {
                c2 = (char) ('a' + random.nextInt(26));
            } while (c1 == c2);
            for (int i = 0; i < len; i++) {
                sb.append(i % 2 == 0 ? c1 : c2);
