public static Object[] generateValidInput(Random random) {
    // Decide on a category: 0 = null, 1 = empty, 2 = single, 3 = two consecutive, 
    // 4 = two non-consecutive, 5 = longer consecutive, 6 = longer non-consecutive,
    // 7 = longer with duplicate, 8 = overflow edge case, 9 = negative consecutive
    int category = random.nextInt(10);

    int[] arr = null;
    switch (category) {
        case 0: // null array
            break;
        case 1: // empty array
            arr = new int[0];
            break;
        case 2: // single element – random value, including boundary
            int singleVal = random.nextInt(10) < 3 ? 
                (random.nextBoolean() ? Integer.MIN_VALUE : Integer.MAX_VALUE) :
                random.nextInt(200) - 100;
            arr = new int[]{singleVal};
            break;
        case 3: // two consecutive
            int startTwo = random.nextInt(10) < 3 ? 
                (random.nextBoolean() ? Integer.MAX_VALUE - 1 : Integer.MIN_VALUE) :
                random.nextInt(200) - 100;
            arr = new int[]{startTwo, startTwo + 1};
            break;
        case 4: // two non-consecutive (gap of 2 or more)
            int startGap = random.nextInt(200) - 100;
            int gap = 2 + random.nextInt(10); // at least 2 apart
            arr = new int[]{startGap, startGap + gap};
            break;
        case 5: // longer consecutive (length 3 to 10)
            int len = 3 + random.nextInt(8);
            int start = random.nextInt(10) < 3 ? 
                (random.nextBoolean() ? Integer.MAX_VALUE - len + 1 : Integer.MIN_VALUE) :
                random.nextInt(200) - 100;
            // Ensure no overflow for consecutive sequence (if start near MAX_VALUE, length small)
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = start + i;
            }
            break;
        case 6: // longer non-consecutive (insert a gap somewhere)
            len = 3 + random.nextInt(8);
            start = random.nextInt(200) - 100;
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = start + i;
            }
            // Introduce a gap at a random position (except first)
            int gapPos = 1 + random.nextInt(len - 1);
            arr[gapPos] = arr[gapPos - 1] + 2 + random.nextInt(5); // ensure not consecutive
            break;
        case 7: // longer with duplicate (replace one element with previous)
            len = 3 + random.nextInt(8);
            start = random.nextInt(200) - 100;
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = start + i;
            }
            // Duplicate a random element (except first)
            int dupIndex = 1 + random.nextInt(len - 1);
            arr[dupIndex] = arr[dupIndex - 1]; // same as previous
            break;
        case 8: // overflow edge: consecutive sequence crossing MAX_VALUE → MIN_VALUE
            // e.g., {Integer.MAX_VALUE, Integer.MIN_VALUE} is consecutive due to overflow
            arr = new int[]{Integer.MAX_VALUE, Integer.MIN_VALUE};
            break;
        case 9: // negative consecutive
            len = 3 + random.nextInt(5);
            int negStart = -10 - random.nextInt(10);
            arr = new int[len];
            for (int i = 0; i < len; i++) {
                arr[i] = negStart + i;
            }
            break;
    }
    // Note: arr may be null for category 0
    return new Object[]{arr};
}

