    if (random.nextDouble() < 0.1) {
        return new Object[] { null };
    }

    int numTuples = random.nextInt(6); // 0 to 5 tuples
    int[][] tuples = new int[numTuples][];

    for (int i = 0; i < numTuples; i++) {
        // Decide tuple length: 0 to 4 (include empty tuple as edge case)
        int tupleLength = random.nextInt(5); // 0..4
        // But ensure at least 1 for most cases; 25% chance of length 0
        if (tupleLength == 0 && random.nextDouble() < 0.75) {
            tupleLength = 1 + random.nextInt(4); // 1..4
        }
        tuples[i] = new int[tupleLength];

        for (int j = 0; j < tupleLength; j++) {
            // Choose value with diverse ranges
            int value;
            double choice = random.nextDouble();
            if (choice < 0.2) {
                // Special values
                int special = random.nextInt(5);
                switch (special) {
                    case 0: value = 0; break;
                    case 1: value = 1; break;
                    case 2: value = -1; break;
                    case 3: value = Integer.MAX_VALUE; break;
                    default: value = Integer.MIN_VALUE;
