    // Decide whether to produce null array (with ~10% probability)
    if (random.nextDouble() < 0.1) {
        return new Object[] { null };
    }

    // Generate array length: include edge cases 0, 1, 2, and larger sizes
    int n;
    double choice = random.nextDouble();
    if (choice < 0.2) {
        n = 0;
    } else if (choice < 0.4) {
        n = 1;
    } else if (choice < 0.6) {
        n = 2;
    } else {
        n = random.nextInt(18) + 3; // 3 to 20
    }

    // Build a sorted array of distinct integers
    int[] sorted = new int[n];
    if (n > 0) {
        // Start with a random base value, possibly extreme
        int base;
        double baseChoice = random.nextDouble();
        if (baseChoice < 0.1) {
            base = Integer.MIN_VALUE;
        } else if (baseChoice < 0.2) {
            base = Integer.MAX_VALUE - n * 10;
        } else {
            base = random.nextInt(2000) - 1000;
        }
        sorted[0] = base;
        for (int i = 1; i < n; i++) {
            // Ensure distinct and increasing by adding a positive random step
            int step = random.nextInt(10) + 1;
            // Avoid overflow when near MAX_VALUE
            if (sorted[i - 1] > Integer.MAX_VALUE - step) {
                sorted[i] = sorted[i - 1] + 1;
            } else {
                sorted[i] = sorted[i - 1] + step;
            }
        }
    }

    // Rotate the sorted array by a random amount (0 <= k < n)
    int[] rotated;
    if (n == 0) {
        rotated = new int[0];
    } else {
        int k = random.nextInt(n); // rotation count; 0 means no rotation
        rotated = new int[n];
        for (int i = 0; i < n; i++) {
            rotated[i] = sorted[(i + k) % n];
        }
    }

    return new Object[] { rotated };
}

