import java.math.*;

class RightInsertion {

    /*@ requires a != null;
      @ requires (\forall int i; 0 <= i && i < a.length - 1; a[i] <= a[i+1]);
      @ ensures 0 <= \result && \result <= a.length;
      @ ensures \result == 0 || a[\result - 1] <= x;
      @ ensures \result == a.length || a[\result] >= x;
      @ assignable \nothing;
      @ pure
      @*/
    public static int rightInsertion(int[] a, int x) {
        int i = 0;
        int j = a.length - 1;
        /*@ loop_invariant 0 <= i && i <= j + 1 && j + 1 <= a.length;
          @ loop_invariant i == 0 || a[i - 1] <= x;
          @ loop_invariant j == a.length - 1 || a[j + 1] >= x;
          @ loop_invariant (\forall int k; 0 <= k && k < a.length - 1; a[k] <= a[k+1]);
          @ decreases j - i;
          @*/
        while (i <= j) {
            int mid = (i + j) / 2;
            if (a[mid] == x) {
                return mid;
            } else if (a[mid] < x) {
                i = mid + 1;
            } else {
                j = mid - 1;
            }
        }
        return i;
    }
}

