public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(10);
    int[] input;

    switch (choice) {
        case 0:
            // Empty array
            input = new int[0];
            break;
        case 1:
            // Single 0
            input = new int[]{0};
            break;
        case 2:
            // Single 1
            input = new int[]{1};
            break;
        case 3:
            // Boundary: max length binary (31 bits, avoiding overflow)
            input = new int[31];
            for (int i = 0; i < 31; i++) {
                input[i] = random.nextInt(2);
            }
            break;
        case 4:
            // All zeros
            input = new int[]{0, 0, 0, 0, 0};
            break;
        case 5:
            // All ones
            input = new int[]{1, 1, 1, 1, 1};
            break;
        case 6:
            // Alternating pattern
            input = new int[random.nextInt(10) + 1];
            for (int i = 0; i < input.length; i++) {
                input[i] = (i % 2 == 0) ? 1 : 0;
            }
            break;
        case 7:
            // Random length with random bits
            input = new int[random.nextInt(10) + 1];
            for (int i = 0; i < input.length; i++) {
                input[i] = random.nextInt(2);
            }
            break;
        case 8:
            // Leading zeros
            input = new int[random.nextInt(10) + 2];
            input[0] = 0;
            input[1] = 0;
            for (int i = 2; i < input.length; i++) {
                input[i] = random.nextInt(2);
            }
            break;
        default:
            // Typical example
            input = new int[]{1, 1, 0, 1, 0, 0, 1};
            break;
    }

    return new Object[]{input};
}

