            arr = new int[0];
            arrSize = 0;
            break;
        case 1: // single element
            arr = new int[]{random.nextInt(21) - 10};
            arrSize = 1;
            break;
        case 2: // all odd numbers, one appears odd times
            int n = random.nextInt(5) * 2 + 1; // odd length 1,3,5,7,9
            arr = new int[n];
            int oddElement = random.nextInt(21) - 10;
            if (oddElement % 2 == 0) oddElement++; // ensure odd
            // fill with pairs of different even numbers and one odd element
            int idx = 0;
            while (idx < n) {
                if (idx == n - 1) {
                    arr[idx++] = oddElement;
                } else {
                    int even = random.nextInt(21) - 10;
                    if (even % 2 == 0) even++; // make odd to avoid even elements
                    arr[idx++] = even;
                    arr[idx++] = even;
                }
            }
            arrSize = n;
            break;
        case 3: // random array with varied elements
            arrSize = random.nextInt(10); // 0-9
            arr = new int[arrSize];
            for (int i = 0; i < arrSize; i++) {
                arr[i] = random.nextInt(21) - 10;
            }
            break;
        default: // boundary values
            arrSize = random.nextInt(3) + 1; // 1-3
            arr = new int[arrSize];
            int[] boundaryValues = {Integer.MIN_VALUE, Integer.MAX_VALUE, -1, 0, 1};
            for (int i = 0; i < arrSize; i++) {
                arr[i] = boundaryValues[random.nextInt(boundaryValues.length)];
            }
            break;
    }

    return new Object[]{arr, arrSize};
}

