        n = 2 + random.nextInt(29); // 2..30 inclusive
        k = random.nextInt(n + 1);
        p = random.nextDouble();
    }

    // Occasionally set p to boundary values
    if (random.nextDouble() < 0.1) {
        p = 0.0;
    } else if (random.nextDouble() < 0.1) {
        p = 1.0;
    } else if (random.nextDouble() < 0.1) {
        p = 0.5;
    }

    return new Object[]{n, k, p};
}

