class Zigzag {

    /*@ public normal_behavior
      @ requires n >= 0 && k >= 0 && k <= n;
      @ ensures (n == 0 && k == 0) ==> \result == 1;
      @ ensures (k == 0 && n > 0) ==> \result == 0;
      @ ensures (k > 0) ==> \result == zigzag(n, k - 1) + zigzag(n - 1, n - k);
      @ assignable \nothing;
