        if (len <= 0) return "";
        StringBuilder sb = new StringBuilder();
        String chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        for (int i = 0; i < len; i++) {
            sb.append(chars.charAt(random.nextInt(chars.length())));
        }
        return sb.toString();
    };

    String string;
    String sample;
    int choice = random.nextInt(14); // 14 cases for diverse coverage

    switch (choice) {
        case 0: // Normal: string starts with sample
            sample = randomString.apply(5);
            string = sample + randomString.apply(5);
            break;
        case 1: // Normal: string does not start with sample
            string = randomString.apply(5);
            sample = randomString.apply(5);
            // Ensure not prefix
            if (string.startsWith(sample)) {
                sample = "x" + randomString.apply(4);
            }
            break;
        case 2: // Empty string
            string = "";
            sample = randomString.apply(3);
            break;
        case 3: // Empty sample
            string = randomString.apply(5);
            sample = "";
            break;
        case 4: // Both empty
            string = "";
            sample = "";
            break;
        case 5: // Sample contains regex special character (dot) and matches
            sample = "abc.";
            string = "abcX" + randomString.apply(3);
            break;
        case 6: // Sample contains regex special character (dot) and does not match
            sample = "abc.";
            string = "abd" + randomString.apply(3);
            break;
        case 7: // Sample contains invalid regex: starts with quantifier
            sample = "*";
            string = "hello";
            break;
        case 8: // Sample contains backslash (invalid regex)
            sample = "\\";
            string = "test";
            break;
        case 9: // Sample contains parentheses (valid but may cause matching issues)
            sample = "(hello)";
            string = "(hello) world";
            break;
        case 10: // Very long strings
            sample = randomString.apply(100);
            string = sample + randomString.apply(100);
            break;
        case 11: // String starts with sample, sample has spaces
            sample = "hello world";
            string = "hello world" + randomString.apply(5);
            break;
        case 12: // Null sample (will throw NullPointerException) – test error handling
            string = "some string";
            sample = null;
            break;
        case 13: // Null string (will throw NullPointerException)
            string = null;
            sample = "test";
            break;
        default: // Fallback to normal case
            sample = randomString.apply(5);
            string = sample + randomString.apply(5);
            break;
    }
    return new Object[]{string, sample};
}

