public static Object[] generateValidInput(Random random) {
    int n, k;
    int choice = random.nextInt(5);
    switch (choice) {
        case 0:
            // Normal case: n >= k, with positive values
            n = random.nextInt(20) + 1;
            k = random.nextInt(n) + 1;
            break;
        case 1:
            // Boundary: n == k
            n = random.nextInt(20) + 1;
            k = n;
            break;
        case 2:
            // Boundary: n < k (returns -1)
            n = random.nextInt(20);
            k = n + random.nextInt(5) + 1;
            break;
        case 3:
            // Edge: n is small (1 or 2)
            n = random.nextInt(2) + 1;
            k = random.nextInt(5) + 1;
            break;
        case 4:
            // Edge: large values within int range
            n = random.nextInt(1000) + 500;
            k = random.nextInt(n) + 1;
            break;
        default:
            n = 1;
            k = 1;
    }

    return new Object[]{n, k};
}

