            n = random.nextInt(20);
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = random.nextInt(100) - 50; // range -50 to 49
            }
            break;
        case 1: // Empty array
            n = 0;
            arr = new int[0];
            break;
        case 2: // Single element
            n = 1;
            arr = new int[]{random.nextInt(100) - 50};
            break;
        case 3: // Array with consecutive sequence including duplicates
            int start = random.nextInt(20) - 10;
            int seqLen = random.nextInt(10) + 1;
            n = seqLen + random.nextInt(5);
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                if (i < seqLen) {
                    arr[i] = start + i;
                } else {
                    arr[i] = random.nextInt(100) - 50;
                }
            }
            // Shuffle to avoid sorted input
            for (int i = n - 1; i > 0; i--) {
                int j = random.nextInt(i + 1);
                int temp = arr[i];
                arr[i] = arr[j];
                arr[j] = temp;
            }
            break;
        case 4: // Array with all same elements
            int value = random.nextInt(20) - 10;
            n = random.nextInt(10) + 1;
            arr = new int[n];
            Arrays.fill(arr, value);
            break;
        default: // Array with boundary values
            n = random.nextInt(10) + 2;
            arr = new int[n];
            arr[0] = Integer.MIN_VALUE;
            arr[1] = Integer.MAX_VALUE;
            for (int i = 2; i < n; i++) {
                arr[i] = random.nextInt(200) - 100;
            }
            break;
    }

    return new Object[]{arr, n};
}

