import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;


class LateralsurfaceCuboid {

    /*@ public normal_behavior
      @ requires l > 0 && w > 0 && h > 0;
      @ requires (w*h) <= Integer.MAX_VALUE/2;
      @ requires (l*h) <= Integer.MAX_VALUE/2;
      @ requires (2*w*h + 2*l*h) <= Integer.MAX_VALUE;
      @ ensures \result == 2*(w*h + l*h);
      @ assignable \nothing;
      @*/
    public static int lateralsurfaceCuboid(int l, int w, int h) {
        int res = (w * h) * 2;
        res = res + (l * 2 * h);
        return res;
    }
}

