    public static int frequencyOfSmallest(int n, int[] arr) {
        if (n == 0) {
            return 0; // Handle empty array case if needed
        }

        int min = arr[0];
        int count = 1; // Start count at 1 since we already have the first element

        for (int i = 1; i < n; i++) {
            if (min > arr[i]) {
                min = arr[i];
                count = 1; // Reset count for new minimum
            } else if (min == arr[i]) {
                count++; // Increment count for existing minimum
            }
        }
        return count;
    }
}

