            int same = random.nextBoolean() ? Integer.MIN_VALUE
                    : (random.nextBoolean() ? Integer.MAX_VALUE : random.nextInt(2001) - 1000);
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = same;
            }
            break;
        case 4:
            n = 2 + random.nextInt(9);
            arr = new int[n];
            arr[0] = 100 + random.nextInt(100);
            for (int i = 1; i < n; i++) {
                arr[i] = arr[i - 1] - (1 + random.nextInt(10));
            }
            break;
        case 5:
            n = 2 + random.nextInt(9);
            int minFirst = random.nextBoolean() ? Integer.MIN_VALUE
                    : (random.nextBoolean() ? -1 : random.nextInt(100));
            arr = new int[n];
            arr[0] = minFirst;
            for (int i = 1; i < n; i++) {
                if (random.nextInt(5) == 0) {
                    arr[i] = minFirst;
                } else {
                    long bigger = (long) minFirst + 1 + random.nextInt(100);
                    arr[i] = bigger > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) bigger;
                }
            }
            break;
        case 6:
            n = 3 + random.nextInt(8);
            int minDup = random.nextBoolean() ? Integer.MIN_VALUE
                    : (random.nextBoolean() ? -5 : random.nextInt(20));
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = minDup + 1 + random.nextInt(100);
            }
            int dupCount = 2 + random.nextInt(n - 1);
            boolean[] chosen = new boolean[n];
            int placed = 0;
            while (placed < dupCount) {
                int pos = random.nextInt(n);
                if (!chosen[pos]) {
                    chosen[pos] = true;
                    arr[pos] = minDup;
                    placed++;
                }
            }
