    n = random.nextInt(10) + 1;

    // Edge case: n = 1
    if (random.nextBoolean()) {
        n = 1;
    }

    a = new int[n];

    // Generate array with diverse values
    for (int i = 0; i < n; i++) {
        int choice = random.nextInt(5);
        switch (choice) {
            case 0: // Small positive values
                a[i] = random.nextInt(20) + 1;
                break;
            case 1: // Negative values
                a[i] = -random.nextInt(20) - 1;
                break;
            case 2: // Boundary values
                int[] boundaries = {0, 1, -1, Integer.MAX_VALUE, Integer.MIN_VALUE};
                a[i] = boundaries[random.nextInt(boundaries.length)];
                break;
            case 3: // Values with divisibility relationships
                if (i > 0 && random.nextBoolean()) {
                    a[i] = a[i-1] * 2;
                } else {
                    a[i] = random.nextInt(100) + 1;
                }
                break;
            default: // Larger random values
                a[i] = random.nextInt(1000) - 500;
                break;
        }
    }

    // Occasionally create arrays with many divisibility relationships
    if (random.nextBoolean()) {
        int base = random.nextInt(10) + 1;
        for (int i = 0; i < n; i++) {
            a[i] = base * (i + 1);
        }
    }

    return new Object[]{a, n};
}

