            }
            // Rotate array
            for (int i = 0; i < n; i++) {
                arr[(i + rotationPoint) % n] = sorted[i];
            }
            break;
        case 3:
            // Already sorted array
            n = random.nextInt(10) + 1;
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = i * 3 + random.nextInt(2);
            }
            break;
        default:
            // Fully rotated array (sorted but rotated such that minimum is at start)
            n = random.nextInt(10) + 2;
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = i * 2;
            }
            // Rotate by n-1 to get max rotation
            int[] rotated = new int[n];
            for (int i = 0; i < n; i++) {
                rotated[(i + n - 1) % n] = arr[i];
            }
            arr = rotated;
            break;
    }

    return new Object[]{arr, n};
}

