import java.io.*;
import java.lang.*;
import java.util.*;
import java.math.*;

class CountRotation {

    /*@ public normal_behavior
      @ requires arr != null && n >= 0 && n <= arr.length;
      @ ensures n == 0 ==> \result == 0;
      @ ensures n > 0 ==> \result >= 1 && \result <= n;
      @ assignable \nothing;
      @*/
    public static int countRotation(int[] arr, int n) {
        if (n == 0) {
            return 0;
        }
        int left = 0, right = n - 1;
        //@ maintaining 0 <= left && left <= right && right < n;
        //@ decreases right - left;
        while (left < right) {
            if (arr[left] < arr[right]) {
                return left + 1;
            }
            int mid = (left + right) / 2;
            if (arr[mid] > arr[left]) {
                left = mid;
            } else {
                right = mid;
            }
        }
        return left + 1;
    }
}

