            // Empty array
            a = new int[0];
            x = random.nextInt(21) - 10;
            break;
        case 1:
            // Single element array
            a = new int[]{random.nextInt(21) - 10};
            x = random.nextInt(21) - 10;
            break;
        case 2:
            // Small sorted array with random values
            int len = random.nextInt(5) + 1;
            a = new int[len];
            int val = random.nextInt(11) - 5;
            for (int i = 0; i < len; i++) {
                a[i] = val;
                val += random.nextInt(3);
            }
            x = random.nextInt(21) - 10;
            break;
        case 3:
            // Array with duplicates
            a = new int[]{1, 1, 2, 2, 3, 3};
            x = random.nextInt(5);
            break;
        case 4:
            // Boundary values
            a = new int[]{Integer.MIN_VALUE, -1, 0, 1, Integer.MAX_VALUE};
            x = random.nextBoolean() ? Integer.MIN_VALUE : Integer.MAX_VALUE;
            break;
        case 5:
            // x before all elements
            a = new int[]{5, 10, 15, 20};
            x = random.nextInt(5) - 5;
            break;
        case 6:
            // x after all elements
            a = new int[]{5, 10, 15, 20};
            x = random.nextInt(5) + 21;
            break;
        case 7:
            // x equal to an existing element
            a = new int[]{1, 2, 4, 5, 7};
            int[] choices = {1, 2, 4, 5, 7};
            x = choices[random.nextInt(choices.length)];
            break;
        case 8:
            // Random sorted array with random values
            int size = random.nextInt(10);
            a = new int[size];
            int current = random.nextInt(100) - 50;
            for (int i = 0; i < size; i++) {
                a[i] = current;
                current += random.nextInt(5);
            }
            x = random.nextInt(200) - 100;
            break;
        default:
            // Null array (if allowed by method)
            a = null;
            x = random.nextInt(100) - 50;
            break;
    }

    return new Object[]{a, x};
}

