public static Object[] generateValidInput(Random random) {
    // Decide the type of test case
    int type = random.nextInt(10);

    int[] arr = null;
    int n = 0;

    switch (type) {
        case 0: // null array
            n = random.nextInt(10); // arbitrary n
            arr = null;
            break;
        case 1: // empty array
            n = 0;
            arr = new int[0];
            break;
        case 2: // single element
            n = 1;
            arr = new int[1];
            // choose a variety of single values
            int singleVal = random.nextInt(5);
            switch (singleVal) {
                case 0: arr[0] = 0; break;
                case 1: arr[0] = 1; break;
                case 2: arr[0] = -1; break;
                case 3: arr[0] = Integer.MAX_VALUE; break;
                case 4: arr[0] = Integer.MIN_VALUE; break;
                default: arr[0] = random.nextInt(200) - 100; break;
            }
            break;
        case 3: // all same values
            n = random.nextInt(5) + 1; // 1..5
            arr = new int[n];
            int sameVal = random.nextInt(10) - 5;
            for (int i = 0; i < n; i++) {
                arr[i] = sameVal;
            }
            break;
        case 4: // consecutive increasing by 1
            n = random.nextInt(5) + 1; // 1..5
            arr = new int[n];
            int startInc = random.nextInt(10) - 5;
            for (int i = 0; i < n; i++) {
                arr[i] = startInc + i;
            }
            break;
        case 5: // consecutive decreasing by 1
            n = random.nextInt(5) + 1; // 1..5
            arr = new int[n];
            int startDec = random.nextInt(10) - 5;
            for (int i = 0; i < n; i++) {
                arr[i] = startDec - i;
            }
            break;
        case 6: // random values with small range (differences often <=1)
            n = random.nextInt(6) + 2; // 2..7
            arr = new int[n];
            // generate a base and then add small deviations
            int base = random.nextInt(6) - 3;
            for (int i = 0; i < n; i++) {
                // keep values within 2 of base to get subsequences
                int offset = random.nextInt(3) - 1; // -1,0,1
                arr[i] = base + offset;
                // occasionally add a bigger jump
                if (random.nextDouble() < 0.2) {
                    arr[i] = base + random.nextInt(5) - 2;
                }
            }
            break;
        case 7: // random values including extremes
            n = random.nextInt(6) + 1; // 1..6
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                int pick = random.nextInt(4);
                switch (pick) {
                    case 0: arr[i] = Integer.MAX_VALUE; break;
                    case 1: arr[i] = Integer.MIN_VALUE; break;
                    case 2: arr[i] = 0; break;
                    case 3: arr[i] = random.nextInt(200) - 100; break;
                    default: arr[i] = random.nextInt(200) - 100; break;
                }
            }
            break;
        case 8: // boundary values array with duplicates and near boundaries
            n = random.nextInt(5) + 1; // 1..5
            arr = new int[n];
            int[] boundaryVals = {Integer.MIN_VALUE, Integer.MIN_VALUE+1, -1, 0, 1, Integer.MAX_VALUE-1, Integer.MAX_VALUE};
            for (int i = 0; i < n; i++) {
                arr[i] = boundaryVals[random.nextInt(boundaryVals.length)];
            }
            break;
        default: // normal random array with varied values
            n = random.nextInt(8) + 1; // 1..8
            arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = random.nextInt(200) - 100; // range -100..99
            }
            break;
    }

    return new Object[]{arr, n};
}

