            switch (edgeChoice) {
                case 0: arr[i] = Integer.MIN_VALUE; break;
                case 1: arr[i] = Integer.MAX_VALUE; break;
                case 2: arr[i] = 0; break;
                case 3: arr[i] = 1; break;
