    // Decide array length: cover empty, 1, 2, and typical sizes
    int length;
    double r = random.nextDouble();
    if (r < 0.1) {
        length = 0; // empty array
    } else if (r < 0.2) {
        length = 1; // singleton array (front and rear same)
    } else if (r < 0.3) {
        length = 2; // minimal two-element array
    } else {
        // random length between 3 and 20, or occasionally larger
        length = random.nextInt(18) + 3; // 3..20
        if (random.nextDouble() < 0.1) {
            length = random.nextInt(100) + 21; // 21..120
        }
    }

    // Create array
    int[] arr = new int[length];
    if (length > 0) {
        // Fill with random values, but sometimes set boundary values at first and last
        for (int i = 0; i < length; i++) {
            // 20% chance to set a boundary value at specific positions
            if (i == 0 && random.nextDouble() < 0.3) {
                // Choose a boundary value for first element
                int b = random.nextInt(5);
                switch (b) {
                    case 0: arr[i] = Integer.MAX_VALUE; break;
                    case 1: arr[i] = Integer.MIN_VALUE; break;
                    case 2: arr[i] = 0; break;
                    case 3: arr[i] = 1; break;
                    case 4: arr[i] = -1; break;
