    int sum = random.nextInt(2001) - 1000;

    // Sometimes use an extreme sum
    if (random.nextBoolean()) {
        sum = random.nextBoolean() ? Integer.MAX_VALUE : Integer.MIN_VALUE;
    }

    boolean forced = false;
    if (arrSize >= 3 && random.nextBoolean()) {
