class MoveLast {

    /*@ public normal_behavior
      @ requires numArray != null;
      @ assignable \nothing;
      @ ensures \result != null;
      @ ensures \result.length == numArray.length;
      @ ensures numArray.length == 0 ==> \result == numArray;
      @ ensures numArray.length > 0 ==>
      @          (\forall int i; 0 <= i && i < numArray.length - 1;
      @               \result[i] == numArray[i + 1]) &&
      @          \result[numArray.length - 1] == numArray[0];
      @*/
    public static int[] moveLast(int[] numArray) {
        int size = numArray.length;
        if (size == 0) {
            return numArray;  // Return the same array if it's empty
        }

        int[] result = new int[size];

