// Helper method to generate a random string of length between minLen and maxLen
private static String randomString(Random random, int minLen, int maxLen) {
    int len = minLen + (maxLen > minLen ? random.nextInt(maxLen - minLen + 1) : 0);
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        // Generate printable ASCII characters (32-126)
        char c = (char) (random.nextInt(95) + 32);
        sb.append(c);
    }
    return sb.toString();
}

