public static Object[] generateValidInput(Random random) {
    int[] edgeCases = {2, 0, 1, -1, Integer.MAX_VALUE, Integer.MIN_VALUE, 3, 12, 13, 100, -100};
    int selector = random.nextInt(edgeCases.length + 1);
    int monthnum1;
    if (selector < edgeCases.length) {
        monthnum1 = edgeCases[selector];
    } else {
        monthnum1 = random.nextInt();
    }
    return new Object[]{monthnum1};
}

